mapper.select:
select t.protolcol_id,t.protolcol_id protolcolId,t.user_protocol,t.user_protocol
userProtocol,t.merchant_protocol,t.merchant_protocol merchantProtocol,t.create_time,t.create_time
createTime,t.status_cd,t.status_cd statusCd
from register_protocol t
where 1 =1

    and t.protolcol_id= #{protolcolId}


    and t.status_cd= #{statusCd}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update register_protocol t set t.status_cd = #{statusCd}

    , t.user_protocol= #{userProtocol}


    , t.merchant_protocol= #{merchantProtocol}

where 1=1

    and t.protolcol_id= #{protolcolId}

mapper.select:
select count(1) count
from register_protocol t
where 1 =1

    and t.protolcol_id= #{protolcolId}


    and t.status_cd= #{statusCd}
